/**
 * Summarizes research records concurrently into BMW feedback rows matching
 * BMW's feedback export schema (12 columns: ID, Source, Brand, Sales Description,
 * Country, Derivate, Engine Type, Feedback Type, Customer Feedback, Vfc...).
 */
export async function summarizeResearchDataset(
  dataset: ResearchDataset,
  options: SummarizeOptions,
): Promise<ResearchTableRow[]> {
  const signal = options.signal ?? new AbortController().signal;
  const sources = new Map(dataset.sources.map((s) => [s.id, s]));
  const concurrency = Math.max(1, Math.min(options.concurrency ?? 4, 8));
  const rows: ResearchTableRow[] = [];

  type SummarizedEntry = {
    record: ResearchRecord;
    source?: Source;
    items?: SummarizedFeedbackItem[];
    tableRows?: ResearchTableRow[];
    locator?: string;
    selection?: ReturnType<typeof assessedSelection>;
  };

  const summarizedItems = await parallelMap(
    dataset.records,
    concurrency,
    async (record, index): Promise<SummarizedEntry> => {
      signal.throwIfAborted();
      const source = sources.get(record.sourceId);

      // 1. Handle assessedSelection(record):
      // If selection.reviewed && !selection.excerpts.length && !selection.tableRows.size, skip the record (it was excluded by assessment review).
      const selection = assessedSelection(record);
      if (selection.reviewed && !selection.excerpts.length && !selection.tableRows.size) {
        return { record, source, tableRows: [] };
      }

      // 2. Handle record.recordType === "table" and record.table:
      // Rather than summarizing structured table records as if they were unformatted text passages,
      // preserve table records using the existing tabular conversion from tabular.ts (researchTableRows),
      // preserving record.table, table: { ...record.table, rows: [values] }, fields, and original metadata.
      if (
        (record.recordType === "table" && record.table) ||
        sourceAssociations(record).length > 0
      ) {
        const tableRows = researchTableRows({ ...dataset, records: [record] });
        return { record, source, tableRows };
      }

      // 3. If selection.excerpts.length > 0, use the selected excerpts for text extraction rather than the whole text if applicable.
      const extractedText =
        selection.excerpts.length > 0
          ? selection.excerpts.map(({ start, end }) => record.text.slice(start, end)).join("\n\n")
          : record.text;

      const locator =
        selection.reviewed && selection.excerpts.length > 0
          ? `${record.locator ? `${record.locator}, ` : ""}chars ${selection.excerpts.map(({ start, end }) => `${start + 1}–${end}`).join(", ")}`
          : record.locator;

      // If the record already has full BMW originalFields, retain it directly.
      const existing = record.metadata.originalFields as Record<string, unknown> | undefined;
      if (
        existing &&
        typeof existing === "object" &&
        existing["Customer Feedback"] &&
        existing["Vfc level2 Name"]
      ) {
        const summary =
          selection.excerpts.length > 0 ? extractedText : String(existing["Customer Feedback"]);
        return {
          record,
          source,
          locator,
          selection,
          items: [
            {
              brand: String(existing["Brand"] ?? "[BMW]"),
              salesDescription: String(existing["Sales Description"] ?? "[BMW 1 Series]"),
              country: String(existing["Country"] ?? "EU"),
              derivate: String(existing["Derivate (e-code)"] ?? "F70"),
              engineType:
                (existing["Engine Type"] as SummarizedFeedbackItem["engineType"]) ?? "ICE",
              feedbackType:
                (existing["Feedback Type"] as SummarizedFeedbackItem["feedbackType"]) ?? "Likes",
              summary,
              vfcLevel2Name: String(existing["Vfc level2 Name"]),
              vfcLevel3Name: String(existing["Vfc level3 Name"] ?? "Like: function"),
            },
          ],
        };
      }

      // Try summarizing via LLM if available and not purely mock/stub
      if (options.llm && typeof options.llm.generateObject === "function") {
        try {
          const prompt = JSON.stringify({
            contract: "reqflow.research.summarize@1",
            scope: {
              vehicleLine: options.scope.vehicleLine,
              vehicleCode: options.scope.vehicleCode,
              derivative: options.scope.derivative,
              market: options.scope.market,
            },
            source: {
              title: source?.title || record.sourceId,
              publisher: source?.publisher,
              url: source?.uri,
              provider: record.provider,
            },
            content: extractedText.slice(0, 16_000),
          });

          const result = await options.llm.generateObject({
            schema: SourceSummariesResult,
            system: SUMMARIZER_SYSTEM,
            prompt,
            tier: "fast",
            signal: options.signal,
          });

          if (
            result &&
            result.object &&
            Array.isArray(result.object.items) &&
            result.object.items.length > 0
          ) {
            return { record, source, items: result.object.items, locator, selection };
          }
        } catch (error) {
          if (options.signal.aborted) throw error;
          options.log?.(
            `Summarizer LLM skipped for record ${record.id} (${error instanceof Error ? error.message : String(error)}); using structured rule-based summary.`,
          );
        }
      }

      // Offline rule-based fallback
      const offlineItem = offlineSummarizeRecord(record, source, options.scope, extractedText);
      return { record, source, items: [offlineItem], locator, selection };
    },
    signal,
  );

  let seq = 1;
  for (const entry of summarizedItems) {
    if (entry.tableRows) {
      rows.push(...entry.tableRows);
      continue;
    }
    const { record, source, items, locator, selection } = entry;
    if (!items || items.length === 0) continue;
    const columns = Object.fromEntries(BMW_FEEDBACK_HEADERS.map((key) => [key, null]));
    for (const [subIndex, item] of items.entries()) {
      const id = items.length > 1 ? `${record.id}_item${subIndex + 1}` : record.id;
      const vfcFull = `${item.vfcLevel2Name} : ${item.vfcLevel3Name}`;
      const fields: Record<string, unknown> = {
        ...columns,
        ID: id,
        Source: source?.publisher ?? source?.title ?? record.provider,
        Brand: item.brand,
        "Sales Description": item.salesDescription,
        Country: item.country,
        "Derivate (e-code)": item.derivate,
        "Engine Type": item.engineType,
        "Feedback Type": item.feedbackType,
        "Customer Feedback": item.summary,
        "Vfc level2 3 Name": vfcFull,
        "Vfc level2 Name": item.vfcLevel2Name,
        "Vfc level3 Name": item.vfcLevel3Name,
      };

      const row: ResearchTableRow = {
        ...record,
        ...(selection?.reviewed
          ? {
              sourceAssessments: sourceAssessments(record).map(({ agentId, verdict, model }) => ({
                agentId,
                verdict,
                model,
              })),
            }
          : {}),
        id,
        collectedRecordId: record.id,
        text: item.summary,
        locator: locator ?? record.locator,
        fields,
        market: item.country,
        metadata: {
          ...record.metadata,
          originalFields: fields,
        },
        contentHash: createHash("sha256")
          .update(JSON.stringify({ text: item.summary, fields }))
          .digest("hex"),
      };
      rows.push(row);
      seq++;
    }
  }

  return rows;
}

