    tableRows: [],
    model: "test-model",
    summaries: [
      {
        text: "Cold weather conditions reduce battery efficiency by up to 20%.",
        excerpts: [{ start: 0, end: text.length }],
        tableRows: [],
      },
    ],
  };
  record.fields = { ...record.fields, [ASSESSMENT_FIELD]: [assessment] };

